import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Boxes, Layers3, Pencil, Plus, Search, Trash2, TrendingUp } from 'lucide-react';
import { useAdmin } from '../lib/store';
import { EmptyState, Modal, PageHeader, Progress, StatCard, cn } from '../lib/ui';
import { formatUZS, type Category } from '../lib/mock';

const iconChoices = ['🍎', '🥛', '🥖', '🥩', '🍚', '🧃', '🍪', '🧴', '🥦', '🍇', '🧀', '🍫', '🐟', '🥕', '🛒', '🍯'];
const colorChoices = ['#10b981', '#38bdf8', '#f59e0b', '#f43f5e', '#a855f7', '#0ea5e9', '#fb923c', '#64748b'];

const emptyCategory = (): Category => ({
  id: `cat${Date.now()}`,
  name: '',
  icon: '🛒',
  description: '',
  color: '#10b981',
});

export const Categories = () => {
  const { t } = useTranslation();
  const { categories, products, saveCategory, deleteCategory, notify } = useAdmin();
  const [query, setQuery] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Category | null>(null);
  const [draft, setDraft] = useState<Category>(emptyCategory());
  const [toDelete, setToDelete] = useState<Category | null>(null);

  const filtered = useMemo(
    () => categories.filter((c) => `${c.name} ${c.description}`.toLowerCase().includes(query.toLowerCase())),
    [categories, query],
  );

  const statsFor = (id: string) => {
    const list = products.filter((p) => p.categoryId === id);
    return {
      count: list.length,
      value: list.reduce((s, p) => s + p.price * p.stock, 0),
      sold: list.reduce((s, p) => s + p.sold, 0),
    };
  };

  const openCreate = () => {
    setEditing(null);
    setDraft(emptyCategory());
    setModalOpen(true);
  };

  const openEdit = (category: Category) => {
    setEditing(category);
    setDraft({ ...category });
    setModalOpen(true);
  };

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!draft.name.trim()) {
      notify('Kategoriya nomini kiriting', 'error');
      return;
    }
    saveCategory(draft);
    notify(editing ? t('updated') : t('created'));
    setModalOpen(false);
  };

  const totalProducts = products.length;
  const totalValue = products.reduce((s, p) => s + p.price * p.stock, 0);
  const biggest = [...categories].sort((a, b) => statsFor(b.id).count - statsFor(a.id).count)[0];

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('categoriesTitle')}
        subtitle={t('categoriesSubtitle')}
        action={
          <button className="btn-primary btn-sm" onClick={openCreate}>
            <Plus size={16} /> {t('addCategory')}
          </button>
        }
      />

      <div className="mb-5 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label="Kategoriyalar" value={String(categories.length)} icon={<Layers3 size={20} />} />
        <StatCard label={t('totalProducts')} value={String(totalProducts)} icon={<Boxes size={20} />} tone="sky" />
        <StatCard label={t('inventoryValue')} value={formatUZS(totalValue)} icon={<TrendingUp size={20} />} tone="violet" />
        <StatCard label="Eng katta bo'lim" value={biggest?.name ?? '—'} icon={<span className="text-lg">{biggest?.icon}</span>} tone="amber" />
      </div>

      <div className="card mb-5 p-4">
        <div className="relative max-w-sm">
          <Search size={17} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
          <input className="input pl-10" placeholder="Kategoriya qidirish..." value={query} onChange={(e) => setQuery(e.target.value)} />
        </div>
      </div>

      {filtered.length === 0 ? (
        <div className="card">
          <EmptyState title={t('noData')} description="Yangi kategoriya qo'shing." />
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {filtered.map((category) => {
            const stats = statsFor(category.id);
            return (
              <div key={category.id} className="card group overflow-hidden p-5 transition-all duration-300 hover:-translate-y-1">
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div
                      className="flex h-14 w-14 items-center justify-center rounded-2xl text-2xl shadow-sm"
                      style={{ background: `${category.color}1f`, color: category.color }}
                    >
                      {category.icon}
                    </div>
                    <div>
                      <h3 className="font-display text-base font-extrabold">{category.name}</h3>
                      <p className="mt-0.5 text-xs text-[var(--muted)]">{category.description || 'Tavsif yo\'q'}</p>
                    </div>
                  </div>
                  <div className="flex gap-1 opacity-0 transition-opacity group-hover:opacity-100">
                    <button className="icon-btn h-8 w-8" onClick={() => openEdit(category)}><Pencil size={13} /></button>
                    <button className="icon-btn h-8 w-8 text-rose-500" onClick={() => setToDelete(category)}><Trash2 size={13} /></button>
                  </div>
                </div>

                <div className="mt-5 grid grid-cols-3 gap-2">
                  <div className="card-soft p-2.5 text-center">
                    <p className="font-display text-lg font-extrabold">{stats.count}</p>
                    <p className="text-[10px] font-bold text-[var(--muted)]">{t('productsCount')}</p>
                  </div>
                  <div className="card-soft p-2.5 text-center">
                    <p className="font-display text-lg font-extrabold">{stats.sold}</p>
                    <p className="text-[10px] font-bold text-[var(--muted)]">sotilgan</p>
                  </div>
                  <div className="card-soft p-2.5 text-center">
                    <p className="truncate font-display text-sm font-extrabold">{formatUZS(stats.value).replace(" so'm", '')}</p>
                    <p className="text-[10px] font-bold text-[var(--muted)]">so'm</p>
                  </div>
                </div>

                <div className="mt-4">
                  <div className="mb-1.5 flex items-center justify-between text-[10px] font-bold text-[var(--muted)]">
                    <span>Katalogdagi ulush</span>
                    <span>{totalProducts ? Math.round((stats.count / totalProducts) * 100) : 0}%</span>
                  </div>
                  <Progress value={totalProducts ? (stats.count / totalProducts) * 100 : 0} />
                </div>
              </div>
            );
          })}

          <button
            onClick={openCreate}
            className="flex min-h-[210px] flex-col items-center justify-center gap-2 rounded-2xl border-2 border-dashed p-6 text-[var(--muted)] transition hover:border-brand-500 hover:bg-brand-500/5 hover:text-brand-600 dark:hover:text-brand-400"
            style={{ borderColor: 'var(--border)' }}
          >
            <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[var(--surface-3)]">
              <Plus size={22} />
            </span>
            <span className="text-sm font-extrabold">{t('addCategory')}</span>
            <span className="text-xs">Yangi bo'lim yarating</span>
          </button>
        </div>
      )}

      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={editing ? t('editCategory') : t('addCategory')}>
        <form onSubmit={submit} className="space-y-4">
          <div>
            <label className="label">{t('name')}</label>
            <input className="input" value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="Masalan: Meva va sabzavot" />
          </div>
          <div>
            <label className="label">{t('description')}</label>
            <input className="input" value={draft.description} onChange={(e) => setDraft({ ...draft, description: e.target.value })} placeholder="Qisqa tavsif" />
          </div>
          <div>
            <label className="label">{t('icon')}</label>
            <div className="flex flex-wrap gap-1.5">
              {iconChoices.map((icon) => (
                <button
                  key={icon}
                  type="button"
                  onClick={() => setDraft({ ...draft, icon })}
                  className={cn('flex h-10 w-10 items-center justify-center rounded-xl border text-lg transition hover:scale-105', draft.icon === icon && 'border-brand-500 ring-2 ring-brand-500/20')}
                  style={{ borderColor: draft.icon === icon ? undefined : 'var(--border)' }}
                >
                  {icon}
                </button>
              ))}
            </div>
          </div>
          <div>
            <label className="label">Rang</label>
            <div className="flex flex-wrap gap-2">
              {colorChoices.map((color) => (
                <button
                  key={color}
                  type="button"
                  onClick={() => setDraft({ ...draft, color })}
                  className={cn('h-9 w-9 rounded-xl transition hover:scale-110', draft.color === color && 'ring-2 ring-offset-2 ring-offset-[var(--surface)]')}
                  style={{ background: color, boxShadow: draft.color === color ? `0 0 0 2px ${color}` : undefined }}
                />
              ))}
            </div>
          </div>
          <div className="flex gap-2 pt-1">
            <button type="button" className="btn-secondary flex-1" onClick={() => setModalOpen(false)}>{t('cancel')}</button>
            <button type="submit" className="btn-primary flex-1">{editing ? t('save') : t('add')}</button>
          </div>
        </form>
      </Modal>

      <Modal open={!!toDelete} onClose={() => setToDelete(null)} title={t('delete')} subtitle={t('confirmDelete')}>
        <div className="flex items-center gap-3 rounded-2xl bg-rose-500/10 p-3">
          <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-rose-500/15 text-xl">{toDelete?.icon}</span>
          <p className="text-sm font-extrabold">{toDelete?.name}</p>
        </div>
        <div className="mt-5 flex gap-2">
          <button className="btn-secondary flex-1" onClick={() => setToDelete(null)}>{t('cancel')}</button>
          <button
            className="btn flex-1 bg-rose-500 text-white hover:bg-rose-600"
            onClick={() => {
              if (toDelete) {
                deleteCategory(toDelete.id);
                notify(t('deleted'));
              }
              setToDelete(null);
            }}
          >
            {t('delete')}
          </button>
        </div>
      </Modal>
    </div>
  );
};
